/* Source: supplied recruitment notice, personal statement and interview notes. */
(function(root){
const row=(id,category,text,model,keys,criteria,follow)=>({id,category,text,model,keys,criteria:criteria.map(([label,pattern])=>({label,pattern})),follow});
const Q=[
row('intro','지원동기','검역지원 근무 경험을 포함해 본인을 소개해 주세요.','저는 인천공항지역본부에서 여행객 안내와 검역 보조, 소독시설 관리를 경험했습니다. 중국어 소통 능력과 꼼꼼한 기록 습관으로 검역관의 업무를 성실하게 지원하겠습니다.',['현장 경험','중국어','성실한 지원'],[['직접 수행한 검역 업무','여행객|검역.*보조|소독시설|소독조'],['중국어 또는 기록 역량','중국어|HSK|기록|일지'],['기여 의지','지원하|돕|도움|기여|성실|책임']], '그 경험을 이번 업무에 어떻게 활용하겠습니까?'),
row('motivation','지원동기','같은 기관의 검역지원요원에 다시 지원한 이유는 무엇입니까?','이전 근무를 통해 정확한 안내와 시설 관리가 검역 현장을 뒷받침한다는 것을 배웠습니다. 익힌 현장 경험을 활용하고 현재 업무 지침을 다시 확인하며 책임 있게 일하고 싶어 지원했습니다.',['배운 점','현장 경험','책임감'],[['이전 근무 경험','이전|근무|경험'],['지원 업무의 가치','안내|관리|검역|보호'],['현재 기준 확인과 기여','지침|확인|책임|기여|성실']], '이전 근무 이후 절차가 바뀌었다면 어떻게 하겠습니까?'),
row('strength','지원동기','다른 지원자와 비교했을 때 본인의 직무 강점은 무엇입니까?','저의 강점은 같은 현장에서 검역지원 업무를 경험했고 중국어로 소통할 수 있다는 점입니다. 업무 흐름을 빠르게 익히고 중화권 여행객에게 절차를 정확하게 안내하겠습니다.',['동일 현장','중국어','빠른 적응'],[['현장 경험','경험|근무|현장'],['구체적 역량','중국어|HSK|기록|소독'],['직무 활용','안내|적응|익히|익혀|지원|활용']], '그 강점이 도움이 된 실제 상황을 말씀해 주세요.'),
row('weakness','지원동기','업무를 수행하며 보완해야 할 점과 개선 방법을 말씀해 주세요.','익숙한 업무라도 이전 방식에만 기대지 않도록 주의하겠습니다. 변경된 지침을 메모하고 담당자에게 확인해 현재 기준에 맞게 하겠습니다.',['자기 점검','메모','확인'],[['보완점 인식','보완|부족|주의|의존|개선'],['구체적 개선 행동','메모|학습|교육|연습|확인'],['업무 정확성','지침|기준|정확|담당자']], '그 방법을 꾸준히 실천했는지 어떻게 확인하겠습니까?'),
row('closing','지원동기','마지막으로 면접관에게 하고 싶은 말을 해 주세요.','저는 검역지원 현장에서 결근 없이 맡은 업무를 수행한 경험이 있습니다. 현장 경험과 중국어 능력을 바탕으로 정확하게 안내하고 성실하게 보고하는 지원요원이 되겠습니다.',['근무 경험','중국어','정확한 보고'],[['경력 또는 역량','경험|근무|중국어|군견'],['직무 기여','안내|검역|기록|소독|보고'],['책임 있는 태도','성실|책임|꾸준|정확|지침']], '입사 후 가장 먼저 확인할 것은 무엇입니까?'),
row('agency','기관·직무','농림축산검역본부는 어떤 역할을 하는 기관입니까?','동식물과 관련 물품의 검역 등을 통해 해외 병해충과 가축전염병의 유입을 막는 기관입니다. 저는 여행객 안내와 소독시설 관리 등 현장 지원 업무로 농축산업 보호에 보탬이 되겠습니다.',['국경검역','유입 방지','농축산업 보호'],[['검역 대상 이해','동식물|동물|식물|축산|농축산'],['유입 방지 목적','전염병|병해충|유입|방지'],['지원요원의 역할','안내|소독|보조|지원']], '지원요원이 그 역할에 어떻게 기여할 수 있습니까?'),
row('ministry','기관·직무','농림축산식품부의 역할과 검역 업무의 관계를 설명해 주세요.','농림축산식품부는 농업과 축산업, 식품 분야의 정책을 담당합니다. 검역본부의 국경검역은 해외 가축전염병과 병해충 유입을 막아 농축산업을 보호하는 역할을 합니다.',['농축산 정책','국경검역','산업 보호'],[['부처의 정책 분야','농업|축산|식품'],['검역의 목적','유입|병해충|전염병'],['보호 대상','농축산업|농업|축산업|보호']], '현장 안내가 유입 방지에 중요한 이유는 무엇입니까?'),
row('boundary','기관·직무','검역지원요원과 검역관의 역할은 어떻게 다릅니까?','검역지원요원은 검역관의 지시에 따라 안내와 시설 관리, 검색·수거 보조를 수행합니다. 반입 가능 여부처럼 판단이 필요한 사항은 임의로 처리하지 않고 검역관에게 보고하겠습니다.',['현장 보조','판단 구분','검역관 보고'],[['지원 업무 범위','안내|시설|검색|수거|보조'],['임의 판단 금지','임의로.*않|판단.*않|검역관.*판단|검역관.*확인'],['보고 체계','보고|지시|담당자.*확인']], '여행객이 즉시 답을 달라고 재촉하면 어떻게 하겠습니까?'),
row('duties','기관·직무','채용되면 어떤 업무를 하게 되는지 설명해 주세요.','축산관계자 신고 안내와 소독, 소독시설 관리와 업무일지 작성, 동식물 검역 보조를 수행합니다. 검역관의 지시에 따라 검색과 수거 등을 돕고 평소와 다른 점은 바로 보고하겠습니다.',['신고 안내','시설 관리','검역 보조'],[['신고·소독 안내','신고|축산관계자|여행객.*안내'],['시설 관리·기록','시설|소독조|일지|기록'],['검역 보조·보고','검색|수거|보조|보고']], '이 중 이전에 직접 맡았던 업무는 무엇입니까?'),
row('disease','기관·직무','해외 가축전염병 유입을 막기 위해 지원요원이 지켜야 할 원칙은 무엇입니까?','현재 업무 지침에 따라 신고와 소독 절차를 정확하게 안내하겠습니다. 반입 물품이나 시설에서 확인이 필요한 사항을 발견하면 바로 검역관에게 보고하고 기록하겠습니다.',['현행 지침','정확한 안내','보고와 기록'],[['현행 기준 준수','지침|기준|절차'],['신고·소독 수행','신고|소독|안내'],['보고·기록','보고|기록']], '지침 변경은 어떤 자료로 확인하겠습니까?'),
row('meat','현장 대응','여행객이 육가공품을 신고하지 않고 가져가겠다고 하면 어떻게 하겠습니까?','먼저 신고와 검역 절차가 필요하다는 점을 차분히 안내하겠습니다. 반입 가능 여부를 임의로 판단하지 않고 검역관에게 보고해 지시에 따르겠습니다.',['차분한 안내','임의 판단 금지','보고'],[['신고·검역 안내','신고|검역.*절차|절차.*안내'],['차분한 응대','차분|설명|정중|이해'],['검역관 연결','검역관|담당자|보고']], '여행객이 안내를 거부하고 큰 소리를 내면 어떻게 하겠습니까?'),
row('unknown','현장 대응','반입 가능 여부를 모르는 물품에 대해 여행객이 물으면 어떻게 답하겠습니까?','확인 후 안내하겠다고 말씀드리고 임의로 답하지 않겠습니다. 현행 기준과 검역관의 확인을 거쳐 정확한 절차를 안내하겠습니다.',['확인 요청','임의 답변 금지','정확한 안내'],[['불확실성 인지','모르|불분명|확인|불확실'],['검역관·기준 확인','검역관|담당자|지침|기준'],['후속 안내','안내|설명|전달']], '확인하는 동안 다른 여행객이 몰리면 어떻게 하겠습니까?'),
row('angry','현장 대응','여행객이 검역 절차에 강하게 항의하면 어떻게 대응하겠습니까?','먼저 불편 사항을 듣고 필요한 절차를 차분하게 설명하겠습니다. 혼자 해결하기 어렵거나 안전이 우려되면 바로 검역관에게 보고하고 지시에 따르겠습니다.',['경청','절차 설명','보고'],[['불편 사항 경청','듣|경청|불편.*확인'],['차분한 절차 안내','차분|설명|절차|정중'],['보고·안전 확보','보고|검역관|안전|담당자']], '상대가 계속 같은 요구를 반복하면 어떻게 하겠습니까?'),
row('equipment','현장 대응','야간근무 중 소독시설의 이상을 발견하면 어떻게 하겠습니까?','먼저 안전을 확인하고 이상 내용과 위치를 담당자에게 바로 보고하겠습니다. 지시에 따라 조치하고 시설 상태와 조치 내용을 기록해 다음 근무자에게 전달하겠습니다.',['안전 확인','즉시 보고','기록·인계'],[['안전 우선','안전|위험'],['즉시 보고','보고|담당자|검역관'],['조치 기록·인계','기록|인계|일지']], '직접 수리할 수 있을 것 같아도 같은 방법으로 대응하겠습니까?'),
row('crowd','현장 대응','입국장이 혼잡하고 여러 여행객이 동시에 질문하면 어떻게 하겠습니까?','안전과 현장 지시를 우선하며 필요한 신고 장소와 절차를 짧게 안내하겠습니다. 혼자 처리하기 어려우면 담당자에게 지원을 요청하고 동료와 역할을 나누겠습니다.',['안전','짧은 안내','지원 요청'],[['우선순위·안전','안전|우선|지시'],['명확한 안내','안내|신고|절차'],['동료와 협력','지원.*요청|동료|협력|역할']], '중국어 안내가 동시에 필요하다면 어떻게 하겠습니까?'),
row('previous','경험 검증','2026년 검역지원요원으로 근무할 때 직접 맡았던 업무를 설명해 주세요.','2026년 3월부터 6월까지 인천공항지역본부에서 검역지원요원으로 근무했습니다. 여행객 신고 안내, 검역물 검색·수거 보조, 발판소독조 관리와 업무일지 작성을 맡았습니다.',['근무 경험','실제 업무','기록'],[['근무 경험','근무|인천공항|3월|6월'],['안내·검역 보조','안내|검색|수거|검역.*보조'],['시설·기록','소독|시설|일지|기록']], '처음 접한 업무는 어떻게 익혔습니까?'),
row('disinfect','경험 검증','발판소독조 관리 업무를 어떤 원칙으로 수행하겠습니까?','기관의 관리 기준에 따라 상태를 확인하고 정해진 세척·보충 절차를 지키겠습니다. 이상이 있으면 담당자에게 보고하고 점검과 조치 내용을 업무일지에 기록하겠습니다.',['관리 기준','상태 점검','보고·기록'],[['기준·절차 준수','기준|절차|지침'],['실제 관리 행동','상태|점검|세척|보충|교체'],['보고·기록','보고|기록|일지']], '관리 기준을 정확히 기억하지 못하면 어떻게 하겠습니까?'),
row('dog','경험 검증','군견 관리 경험이 검역지원 업무에 어떻게 도움이 됩니까?','군견에게 먹이를 주고 생활 공간을 소독하며 건강 상태를 매일 확인하고 기록했습니다. 그때 익힌 관찰과 기록 습관을 소독시설 점검과 평소와 다른 점 보고에 활용하겠습니다.',['군견 관리','관찰·기록','현장 활용'],[['실제 군견 관리','군견|급식|견사|건강|소독'],['관찰·기록 습관','관찰|기록|확인|점검'],['직무 연결','시설|보고|검역|활용']], '평소와 다른 상태를 발견했을 때의 대응 원칙은 무엇입니까?'),
row('learn','경험 검증','처음 접하는 검역 업무는 어떻게 배우겠습니까?','현재 업무 지침과 선임 검역관의 설명을 먼저 확인하고 메모하겠습니다. 이해가 부족한 부분은 질문한 뒤 적용하고 근무 종료 전 수행 내용을 점검하겠습니다.',['지침 확인','메모·질문','수행 점검'],[['공식 기준·교육','지침|검역관|교육|선임'],['학습 행동','메모|질문|확인'],['적용·점검','적용|점검|수행|복습']], '이전에 배운 방법과 새 지시가 다르면 어떻게 하겠습니까?'),
row('attendance','경험 검증','본인의 성실성을 보여 줄 수 있는 경험을 말씀해 주세요.','검역지원요원으로 근무하는 동안 결근 없이 맡은 업무를 했습니다. 교대근무에 맞춰 생활과 체력을 관리하고 근무 종료 전 담당 구역과 기록을 다시 확인하겠습니다.',['결근 없는 근무','생활 관리','마무리 점검'],[['실제 경험','결근|근무|경험'],['시간·체력 관리','교대|체력|시간|생활|출근'],['업무 완결성','확인|기록|마무리|책임']], '예상하지 못한 사정으로 지각할 가능성이 생기면 어떻게 하겠습니까?'),
row('conflict','협업·갈등','동료와 업무 방식이 달라 갈등이 생기면 어떻게 하겠습니까?','먼저 동료의 의견을 듣고 현재 업무 지침과 업무 목적을 함께 확인하겠습니다. 의견이 맞지 않으면 감정적으로 대응하지 않고 담당자에게 사실을 전달해 도움을 받겠습니다.',['경청','기준 확인','사실 전달'],[['동료 의견 경청','듣|경청|의견'],['공통 기준 확인','지침|기준|목적'],['조정·협력','담당자|조정|상의|협력|보고']], '본인의 방식이 더 효율적이라고 확신해도 그렇게 하겠습니까?'),
row('younger','협업·갈등','나이가 어린 동료가 반복해서 시비를 걸면 어떻게 하겠습니까?','나이와 관계없이 동료를 존중하고 감정적으로 맞대응하지 않겠습니다. 사실과 업무 기준을 중심으로 대화하고 반복되어 업무에 지장이 생기면 담당자에게 상담하겠습니다.',['존중','차분한 대화','상담'],[['존중·감정 조절','존중|감정|차분|맞대응.*않'],['사실 중심 대화','사실|대화|기준|업무'],['반복 시 상담','담당자|상담|보고|상급자']], '상담할 때 어떤 내용을 전달하겠습니까?'),
row('handover','협업·갈등','교대근무 인수인계에서 가장 중요하게 전달할 내용은 무엇입니까?','소독시설 상태와 조치 내용, 아직 끝내지 못한 일과 평소와 다른 점을 지정된 양식에 정리하겠습니다. 추가 확인이 필요한 사항은 다음 근무자에게 직접 전달하고 함께 확인하겠습니다.',['시설 상태','미완료 업무','직접 확인'],[['시설·조치 정보','시설|소독|조치'],['미완료·특이사항','미완료|미처리|특이|후속|끝내지 못한|평소와 다른'],['기록·직접 인계','양식|기록|전달|인계']], '상대가 바빠서 인수인계를 듣지 못하면 어떻게 하겠습니까?'),
row('newcomer','협업·갈등','업무에 익숙하지 않은 신규 동료를 어떻게 돕겠습니까?','먼저 정해진 절차와 주의사항을 이해하기 쉽게 설명하겠습니다. 군 복무 중 신규 인원을 지도했던 경험을 살려 이해 여부를 확인하고 필요한 부분을 반복해 안내하겠습니다.',['절차 설명','지도 경험','이해 확인'],[['절차 중심 설명','절차|설명|주의|안내'],['경험 활용','군|지도|경험|신규'],['이해 확인','이해|반복|확인']], '동료가 같은 실수를 반복하면 어떻게 하겠습니까?'),
row('mistake','협업·갈등','업무 중 본인의 실수를 발견하면 어떻게 하겠습니까?','실수 내용을 숨기지 않고 담당자에게 바로 보고하겠습니다. 지시에 따라 바로잡고 원인과 조치 내용을 기록해 같은 실수가 반복되지 않도록 하겠습니다.',['즉시 보고','조치','재발 방지'],[['정직한 보고','보고|숨기지|알리'],['지시 따른 조치','지시|조치|바로잡|수정'],['재발 방지','원인|기록|반복|재발']], '동료가 보고하지 말자고 하면 어떻게 하겠습니까?'),
row('ethics','태도·소통','공무직근로자로서 가장 중요한 태도는 무엇이라고 생각합니까?','정해진 기준을 성실하게 지키고 모든 여행객에게 공정하게 안내하는 태도가 중요하다고 생각합니다. 맡은 업무는 끝까지 확인하고 판단이 필요한 사항은 정확하게 보고하겠습니다.',['성실','공정','책임'],[['성실·책임','성실|책임|끝까지'],['공정·기준','공정|기준|지침|동일'],['실천 행동','확인|보고|안내|기록']], '그 태도를 보여 주는 구체적인 행동은 무엇입니까?'),
row('gift','태도·소통','여행객이 편의를 봐 달라며 사례를 제안하면 어떻게 하겠습니까?','금품이나 부당한 편의 제공 요청은 정중히 거절하겠습니다. 모든 여행객에게 같은 기준을 적용하고 필요한 사항은 담당자에게 보고하겠습니다.',['정중한 거절','동일 기준','보고'],[['명확한 거절','거절|받지|응하지'],['공정한 기준','동일|공정|기준|원칙'],['보고 체계','담당자|보고|검역관']], '작은 선물일 뿐이라고 주장하면 어떻게 답하겠습니까?'),
row('privacy','태도·소통','업무 중 알게 된 여행객의 개인정보는 어떻게 다루겠습니까?','개인정보는 업무 목적에 필요한 범위에서만 다루고 기관의 관리 기준을 지키겠습니다. 개인적으로 저장하거나 외부에 공유하지 않고 의심 상황은 담당자에게 보고하겠습니다.',['업무 목적','외부 공유 금지','관리 기준'],[['목적 제한','업무.*목적|필요.*범위'],['보호 행동','공유하지|저장하지|유출|보호|외부'],['기관 기준·보고','기준|지침|보고|담당자']], '지인이 여행객 정보를 물어보면 어떻게 하겠습니까?'),
row('chinese','태도·소통','중국어를 사용하는 여행객을 어떻게 안내하겠습니까? 한국어로 대응 절차를 설명해 주세요.','중국어로 신고 장소와 필요한 검역 절차를 짧고 쉽게 설명하겠습니다. 공식 안내자료와 확인된 표현을 사용하고 전문 지식이 필요한 질문은 검역관에게 연결하겠습니다.',['쉬운 중국어','공식 자료','검역관 연결'],[['중국어 소통','중국어|중화권'],['정확한 절차·자료','절차|신고|공식|자료'],['업무 범위 준수','검역관|확인|연결|보고']], '중국어로도 정확한 표현이 떠오르지 않으면 어떻게 하겠습니까?'),
row('shift','태도·소통','야간 교대근무와 장시간 걷는 업무에 어떻게 대비하겠습니까?','이전 검역지원 근무에서 입국장과 사무실을 오가며 현장 업무를 했습니다. 교대 일정에 맞춰 수면과 체력을 관리하고 안전수칙을 지켜 집중력을 유지하겠습니다.',['현장 경험','수면·체력','안전'],[['근무 경험','경험|근무|입국장'],['생활·체력 관리','수면|체력|생활|휴식'],['안전·집중','안전|집중|수칙']], '피로로 업무 집중력이 떨어질 때 어떻게 대응하겠습니까?')
];
root.QUESTION_BANK=Q;if(typeof module!=='undefined')module.exports=Q;
})(typeof window==='undefined'?globalThis:window);
